begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
insert into academy.stories(id,slug,title_en) values('08000000-0000-4000-8000-000000000001','budget-sql-fixture','Synthetic budget fixture');
select lives_ok($$select academy.budget_configure('2098-01-01',1000,'{"news_analysis":200,"content":300,"voice":200,"video":300}',600,400)$$,'Configure four production envelopes');
select lives_ok($$select academy.budget_configure('2098-01-01',1000,'{"news_analysis":200,"content":300,"voice":200,"video":300}',600,400)$$,'Configuration retry is idempotent');
select throws_ok($$select academy.budget_configure('2098-01-01',2000,'{"news_analysis":200,"content":300,"voice":200,"video":300}',600,400)$$,'22023','BUDGET_PLAN_ALREADY_SET','Cannot silently overwrite plan');
select lives_ok($$select academy.budget_reserve('budget-sql:news','2098-01-01','news_analysis',100,'08000000-0000-4000-8000-000000000001',null,'fixture','1','fixture/1',repeat('a',64))$$,'Reserve analysis');
select is((academy.budget_reserve('budget-sql:news','2098-01-01','news_analysis',100,'08000000-0000-4000-8000-000000000001',null,'fixture','1','fixture/1',repeat('a',64))).id,(select id from academy.budget_operations where idempotency_key='budget-sql:news'),'Retry reuses one reservation');
select throws_ok($$select academy.budget_reserve('budget-sql:news','2098-01-01','news_analysis',101,'08000000-0000-4000-8000-000000000001',null,'fixture','1','fixture/1',repeat('a',64))$$,'22023','BUDGET_KEY_CONFLICT','Changed cost cannot reuse key');
select lives_ok($$select academy.budget_start((select id from academy.budget_operations where idempotency_key='budget-sql:news'))$$,'Dispatch obtains one token');
select throws_ok($$select academy.budget_start((select id from academy.budget_operations where idempotency_key='budget-sql:news'))$$,'P0001','BUDGET_NOT_DISPATCHABLE','Duplicate dispatch is blocked');
select lives_ok($$select academy.budget_settle(id,execution_token,80,'{"input_tokens":5}','receipt:1') from academy.budget_operations where idempotency_key='budget-sql:news'$$,'Settle actual usage');
select lives_ok($$select academy.budget_settle(id,execution_token,80,'{"input_tokens":5}','receipt:1') from academy.budget_operations where idempotency_key='budget-sql:news'$$,'Settlement retry is idempotent');
select throws_ok($$select academy.budget_settle(id,execution_token,81,'{"input_tokens":5}','receipt:1') from academy.budget_operations where idempotency_key='budget-sql:news'$$,'22023','BUDGET_RECEIPT_CONFLICT','Receipt cannot be rewritten');
select is((select spent_micros from academy.budget_summary where month='2098-01-01'),80::numeric,'Actual amount replaces reserve');
select lives_ok($$select academy.budget_reserve('budget-sql:voice','2098-01-01','voice',150,'08000000-0000-4000-8000-000000000001','video:1','fixture','1','fixture/1',repeat('b',64))$$,'Reserve voice for video');
select throws_ok($$select academy.budget_reserve('budget-sql:video','2098-01-01','video',260,'08000000-0000-4000-8000-000000000001','video:1','fixture','1','fixture/1',repeat('c',64))$$,'P0001','BUDGET_LIMIT','Voice and render share a video cap');
select throws_ok($$select academy.budget_reserve('budget-sql:voice-extra','2098-01-01','voice',51,'08000000-0000-4000-8000-000000000001','video:2','fixture','1','fixture/1',repeat('d',64))$$,'P0001','BUDGET_LIMIT','Category cap applies across videos');
select academy.budget_reserve('budget-sql:content','2098-01-01','content',300,'08000000-0000-4000-8000-000000000001',null,'fixture','1','fixture/1',repeat('e',64));
select throws_ok($$select academy.budget_reserve('budget-sql:story','2098-01-01','video',71,'08000000-0000-4000-8000-000000000001','video:3','fixture','1','fixture/1',repeat('f',64))$$,'P0001','BUDGET_LIMIT','Story cap includes all production tools');
select academy.budget_start(id) from academy.budget_operations where idempotency_key='budget-sql:voice';
select academy.budget_uncertain(id,execution_token) from academy.budget_operations where idempotency_key='budget-sql:voice';
select throws_ok($$select academy.budget_release(id) from academy.budget_operations where idempotency_key='budget-sql:voice'$$,'P0001','BUDGET_RECONCILE_REQUIRED','Ambiguous provider call cannot free money');
select is((select reserved_micros from academy.budget_summary where month='2098-01-01'),450::numeric,'Uncertain voice keeps its full reservation');
update academy.budget_operations set expires_at=now()-interval '1 second' where idempotency_key='budget-sql:content';
select throws_ok($$select academy.budget_start(id) from academy.budget_operations where idempotency_key='budget-sql:content'$$,'P0001','BUDGET_NOT_DISPATCHABLE','Expired undispatched work cannot start');
select academy.budget_reserve('budget-sql:cleanup','2098-01-01','news_analysis',0,null,null,'fixture','1','fixture/1',repeat('0',64));
select is((select state from academy.budget_operations where idempotency_key='budget-sql:content'),'released','Expired undispatched reserve is safely recovered');
select lives_ok($$select academy.budget_settle(id,execution_token,1100,'{"characters":100}','confirmed-overrun') from academy.budget_operations where idempotency_key='budget-sql:voice'$$,'Real bill above reserve is recorded honestly');
select throws_ok($$select academy.budget_reserve('budget-sql:blocked','2098-01-01','video',1,'08000000-0000-4000-8000-000000000001','video:4','fixture','1','fixture/1',repeat('1',64))$$,'P0001','BUDGET_LIMIT','Overrun blocks subsequent work');
select throws_ok($$select academy.budget_start(id) from academy.budget_operations where idempotency_key='budget-sql:cleanup'$$,'P0001','BUDGET_LIMIT','Overrun also blocks work reserved before the receipt');
select ok(not has_function_privilege('authenticated','academy.budget_start(uuid)','execute'),'Editor/reviewer cannot dispatch billed work from web');
select ok(not has_table_privilege('authenticated','academy.budget_operations','insert'),'Browser cannot forge a reservation');
select ok(not has_table_privilege('anon','academy.budget_summary','select'),'Anonymous cannot read budget summary');
insert into auth.users(id,email) values ('08000000-0000-4000-8000-000000000002','budget-reviewer@example.test');
insert into academy.editor_members(user_id,role) values ('08000000-0000-4000-8000-000000000002','reviewer');
set local role authenticated;
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000002',true);
select is((select count(*) from academy.budget_category_summary where month='2098-01-01'),4::bigint,'Reviewer sees all four tool envelopes');
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000099',true);
select is((select count(*) from academy.budget_summary),0::bigint,'Outsider cannot read budget aggregate');
reset role;
select * from finish();
rollback;
